create or replace function public.app_reset_demo()
returns void language plpgsql set search_path = public as $reset$
begin
  delete from public.app_audit_events where true;
  delete from public.app_verification_runs where true;
  delete from public.app_review_tasks where true;
  delete from public.app_recommendations where true;
  delete from public.app_model_runs where true;
  delete from public.app_evidence where true;
  delete from public.app_finding_policy_sources where true;
  delete from public.app_findings where true;
  delete from public.app_scan_jobs where true;
  delete from public.app_scans where true;
  delete from public.app_projects where true;
  perform public.app_seed_demo();
end $reset$;

revoke all on function public.app_seed_demo(), public.app_reset_demo() from public, anon, authenticated;
